/**
 * @brief Soft-timer service thread name / priority / stack size
 * @note the service thread runs the SOFT timer callbacks in thread context; it
 *       sits one priority step ABOVE the idle thread: sharing the lowest level
 *       with the reaper meant any code that locates a thread by priority could
 *       land in the endless idle loop instead of the service thread. It still
 *       never preempts application work and is spawned lazily on the first SOFT
 *       timer start (the scheduler must be up, which happens in main after the
 *       constructors, so it cannot be created from the constructor itself).
 *       MINI_OS_TIMER_THREAD_STACK_SIZE must be >= MINI_OS_THREAD_MIN_STACK_SIZE
 *       and a multiple of 8.
 */
#define MINI_OS_TIMER_THREAD_NAME "timer_thread"             /**< soft-timer service thread name */
#define MINI_OS_TIMER_THREAD_PRIORITY (MINI_OS_PRIORITY - 2) /**< one step above idle: never shares the lowest level */
#ifdef CONFIG_MINI_OS_TIMER_THREAD_STACK_SIZE
#define MINI_OS_TIMER_THREAD_STACK_SIZE CONFIG_MINI_OS_TIMER_THREAD_STACK_SIZE /**< service thread stack bytes */
#elif defined(MINI_OS_TIMER_THREAD_STACK_SIZE)
/* MINI_OS_TIMER_THREAD_STACK_SIZE pre-defined externally , keep it */
#else
#define MINI_OS_TIMER_THREAD_STACK_SIZE 512 /**< service thread stack bytes */
#endif
/**
 * @brief Enable stack overflow detection on the system (MSP) stack
 * @note Off by default; set CONFIG_MINI_OS_STACK_OVERFLOW_CHECK=1 to enable.
 *       Plants a magic word at the stack's low boundary (linker symbol
 *       __mini_os_heap_end from mini-os-heap.ld, where heap ends and the
 *       system stack begins); the idle thread re-checks it every loop and
 *       halts when the stack ran over the boundary into the heap.
 */
#ifdef CONFIG_MINI_OS_STACK_OVERFLOW_CHECK
#define MINI_OS_STACK_OVERFLOW_CHECK CONFIG_MINI_OS_STACK_OVERFLOW_CHECK
#elif defined(MINI_OS_STACK_OVERFLOW_CHECK)
/* MINI_OS_STACK_OVERFLOW_CHECK pre-defined externally , keep it */
#else
#define MINI_OS_STACK_OVERFLOW_CHECK 0
#endif

#define MINI_OS_STACK_MAGIC 0x060815U /**< stack/ overflow sentinel word */

