/**
 * @brief Enable thread detach/join support (adds the per-thread corpse fields)
 * @note Off by default; set CONFIG_MINI_OS_THREAD_DETACH=1 in config.h to enable.
 *       The switch covers mini_os_thread_detach() AND mini_os_thread_join()
 *       together on purpose: they are two halves of the same corpse-lifetime
 *       mechanism and neither works standalone.
 *  - a join pins the corpse (is_detach = MINI_OS_FALSE) so the idle reaper
 *    cannot free the TCB while the return value is still needed, and unpins it
 *    again on success (or restores the previous detach state on timeout)
 *  - detach is only meaningful because a join can pin the corpse in the first
 *    place; without join, is_detach is permanently true and the idle reaper
 *    collects every thread the moment it terminates
 * @note enabling it adds is_detach / is_terminated / exit_retval /
 *       join_wait_sem to every TCB
 */
#ifdef CONFIG_MINI_OS_THREAD_DETACH
#define MINI_OS_THREAD_DETACH CONFIG_MINI_OS_THREAD_DETACH
#elif defined(MINI_OS_THREAD_DETACH)
/* MINI_OS_THREAD_DETACH pre-defined externally , keep it */
#else
#define MINI_OS_THREAD_DETACH 0
#endif

